use kimo_core::color::delivery::inspect;
#[test]fn delivery_bad_paths(){for p in ["","-evil","https://example.invalid/a.mp4","/tmp","/tmp/no-kimo-source-invalid.mp4"]{assert!(inspect(p).is_err());}}
#[test]fn declared_delivery_tags(){let p=std::env::temp_dir().join(format!("kimo-delivery-{}.mp4",std::process::id()));assert!(std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","lavfi","-i","color=c=red:s=32x32:r=25:d=0.1","-c:v","libx264","-color_primaries","bt709","-color_trc","iec61966-2-1","-colorspace","bt709","-color_range","tv",p.to_str().unwrap()]).status().unwrap().success());let v=inspect(p.to_str().unwrap()).unwrap();assert_eq!(v["streams"][0]["color_transfer"],"iec61966-2-1");assert_eq!(v["streams"][0]["width"],32);assert!(v["tag_gaps"][0]["absent_or_unspecified_color_fields"].as_array().unwrap().is_empty());std::fs::remove_file(p).unwrap();}
#[test]fn declared_hevc_frame_mastering(){use kimo_core::{commands::{Session,dispatch},color::{pipeline::export_high,delivery::first_frame_metadata}};use serde_json::json;let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":32,"height":32,"fps":25})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","start":0,"duration":0.1})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"output_gamut":1,"output_transfer":6}})).unwrap();dispatch(&mut s,"set_hdr_mastering",&json!({"metadata":{"red":[0.68,0.32],"green":[0.265,0.69],"blue":[0.15,0.06],"white":[0.3127,0.329],"min_nits":0.005,"max_nits":1000,"max_cll":1000,"max_fall":400}})).unwrap();let path=std::env::temp_dir().join(format!("kimo-sei-{}.mp4",std::process::id()));export_high(&s.project,path.to_str().unwrap(),"hevc10",18).unwrap();let v=first_frame_metadata(path.to_str().unwrap()).unwrap();let data=v["frame_side_data"][0].as_array().unwrap();let m=data.iter().find(|d|d["side_data_type"]=="Mastering display metadata").unwrap();assert_eq!(m["max_luminance"],"10000000/10000");let c=data.iter().find(|d|d["side_data_type"]=="Content light level metadata").unwrap();assert_eq!(c["max_content"],1000);assert_eq!(c["max_average"],400);std::fs::remove_file(path).unwrap();}
